    #[case::ts_function_among_more_terms("src/a.ts", "export function useWatch() {}", "useWatch", &["watch", "form", "values", "subscribe"], 2.0)]
    #[case::rust_function_among_more_terms("src/a.rs", "pub fn use_watch() {}", "use_watch", &["watch", "form", "values", "subscribe"], 2.0)]
    #[case::ts_interface("src/a.ts", "export interface FromRequestParts<S> { run(): void }", "FromRequestParts", &["extractor", "request", "parts"], 2.555_556)]
    #[case::rust_trait("src/a.rs", "pub trait FromRequestParts<S> { fn run(); }", "FromRequestParts", &["extractor", "request", "parts"], 2.555_556)]
    #[case::ts_class("src/a.ts", "export class FromRequestParts {}", "FromRequestParts", &["request", "parts"], 7.0)]
    #[case::rust_struct("src/a.rs", "pub struct FromRequestParts;", "FromRequestParts", &["request", "parts"], 7.0)]
    fn name_match_boost_reads_the_name_the_analyzers_extract(
