        if hy and not hx: gained+=1; print('GAINED id',rb['repo'],x['term'],x['def_rank'],'->',y['def_rank'])
        elif x['def_rank']!=y['def_rank']: print('rank id',rb['repo'],x['term'],x['def_rank'],'->',y['def_rank'])
