import json
import sys

root = sys.argv[1]
runs = {}
for b in ("base", "new"):
    for i in (1, 2):
        try:
            d = json.load(open(f"{root}/target/cmp/b2-{b}-{i}.json"))
        except FileNotFoundError:
            continue
        for r in d["rows"]:
            key = tuple(r[k] for k in list(r)[:3])
            runs.setdefault((b, key), []).append(r)
print(list(d["rows"][0]))
keys = sorted({k for (_, k) in runs})
tot = {"base": 0.0, "new": 0.0}
for k in keys:
    if "monokl" not in k:
        continue
    vals = {}
    for b in ("base", "new"):
        rs = runs.get((b, k), [])
        if rs:
            vals[b] = min(r.get("p50_ms", r.get("p50")) for r in rs)
    if len(vals) == 2:
        tot["base"] += vals["base"]
        tot["new"] += vals["new"]
        print(k, vals["base"], vals["new"], f"{vals['new'] / vals['base']:.3f}")
print("total", tot, tot["new"] / tot["base"])

